store/consumer_test.go.text:
package store_test

import (
	"finite.local/shared-record/store"
	"testing"
)

func TestLearnerConsumerLoad(t *testing.T) {
	got := store.Load("  item  ")
	want := store.Entry{Name: "item", Count: 1}
	if got != want {
		t.Errorf("consumer Load=%+v; want %+v", got, want)
	}
}

store/normalize_test.go.text:
package store

import "testing"

func TestLearnerPrivateNormalization(t *testing.T) {
	for _, tc := range []struct{ in, want string }{{"  a  ", "a"}, {"\t\n", ""}, {" λ ", "λ"}} {
		if got := normalize(tc.in); got != tc.want {
			t.Errorf("private normalize(%q)=%q; want %q", tc.in, got, tc.want)
		}
	}
}

store/public_test.go.text:
package store_test

import (
	"finite.local/shared-record/codec"
	"finite.local/shared-record/record"
	"finite.local/shared-record/store"
	"testing"
)

func TestPublicCompatibilityAndBehavior(t *testing.T) {
	var e record.Entry = store.Entry{Name: "x", Count: 3}
	var legacy store.Entry = e
	if got := codec.Encode(legacy); got != "x:3" {
		t.Errorf("Encode=%q; want x:3", got)
	}
	for _, name := range []string{"", "alpha", "  alpha  "} {
		want := "alpha"
		if name == "" {
			want = ""
		}
		got := store.Load(name)
		if got.Name != want || got.Count != 1 {
			t.Errorf("Load(%q)=%+v; want Name=%q Count=1", name, got, want)
		}
	}
}

